using System;using System.Data;using System.Text;using System.Web.UI.WebControls;
namespace AQOONHUB_SMS.Modules.Communication{public partial class DeliveryLogs:CommunicationPageBase{int P{get{return (int?)(ViewState["P"])??1;}set{ViewState["P"]=Math.Max(1,value);}}int Pages{get{return (int?)(ViewState["Pages"])??1;}set{ViewState["Pages"]=Math.Max(1,value);}}protected void Page_Load(object s,EventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanViewDeliveryLogs);if(!IsPostBack)Bind();}CommPage Data(int page,int size){return Repo.Deliveries(DateValue(txtFrom.Text),DateValue(txtTo.Text),ddlChannel.SelectedValue,ddlStatus.SelectedValue,txtSender.Text.Trim(),txtRecipient.Text.Trim(),txtSearch.Text.Trim(),page,size,UserId,Role);}void Bind(){try{int z=PageSize(ddlPageSize.SelectedValue);CommPage x=Data(P,z);Pages=Math.Max(1,(int)Math.Ceiling(x.Total/(double)z));if(P>Pages){P=Pages;Bind();return;}gv.DataSource=x.Rows;gv.DataBind();litPage.Text="Page "+P+" of "+Pages+" · "+x.Total+" records";btnPrev.Enabled=P>1;btnNext.Enabled=P<Pages;litTotal.Text=x.Total.ToString();DataTable n=Repo.Q("SELECT SUM(CASE WHEN Status='Sent' THEN 1 ELSE 0 END) Sent,SUM(CASE WHEN Status IN('Delivered','Read') THEN 1 ELSE 0 END) Delivered,SUM(CASE WHEN Status='Failed' THEN 1 ELSE 0 END) Failed,SUM(CASE WHEN Status='Pending' THEN 1 ELSE 0 END) Pending FROM dbo.CommunicationDeliveries WHERE (@admin=1 OR CreatedByUserID=@u)",new System.Data.SqlClient.SqlParameter("@admin",CommunicationAuthorization.IsAdmin(Role)),new System.Data.SqlClient.SqlParameter("@u",UserId));DataRow r=n.Rows[0];litSent.Text=N(r["Sent"]);litDelivered.Text=N(r["Delivered"]);litFailed.Text=N(r["Failed"]);litPending.Text=N(r["Pending"]);}catch(Exception){Error("Delivery logs are unavailable. Confirm the Communication migration and database connection.");}}string N(object v){return v==DBNull.Value?"0":Convert.ToString(v);}protected void btnFilter_Click(object s,EventArgs e){P=1;Bind();}protected void btnReset_Click(object s,EventArgs e){txtFrom.Text=txtTo.Text=txtSender.Text=txtRecipient.Text=txtSearch.Text="";ddlChannel.SelectedIndex=ddlStatus.SelectedIndex=0;P=1;Bind();}protected void btnPrev_Click(object s,EventArgs e){P--;Bind();}protected void btnNext_Click(object s,EventArgs e){P++;Bind();}protected void PageSize_Changed(object s,EventArgs e){P=1;Bind();}protected void gv_RowCommand(object s,GridViewCommandEventArgs e){long id;if(e.CommandName!="Details"||!long.TryParse(Convert.ToString(e.CommandArgument),out id))return;DataRow r=Repo.Delivery(id,UserId,Role);if(r==null){Error("Delivery record not found or access denied.");return;}litDetails.Text=D("Communication ID",r["DeliveryID"])+D("Campaign reference",r["CampaignID"])+D("Recipient",r["RecipientAddress"])+D("Channel",r["Channel"])+D("Subject",r["Subject"])+D("Message preview",r["MessagePreview"])+D("Provider",r["ProviderName"])+D("Provider reference",r["ProviderReference"])+D("Status",r["Status"])+D("Attempts",r["AttemptCount"])+D("Sent date",r["SentAt"])+D("Delivery date",r["DeliveredAt"])+D("Read date",r["ReadAt"])+D("Failure reason",r["FailureReason"])+D("Created by",r["CreatedBy"]);pnlDetails.Visible=true;}string D(string k,object v){return "<dt>"+H(k)+"</dt><dd>"+H(v==DBNull.Value?"Unavailable":v)+"</dd>";}protected void btnClose_Click(object s,EventArgs e){pnlDetails.Visible=false;}protected void btnExport_Click(object s,EventArgs e){CommunicationAuthorization.Demand(this,CommunicationAuthorization.CanViewDeliveryLogs);CommPage probe=Data(1,1);CommPage x=Data(1,Math.Max(1,probe.Total));var b=new StringBuilder("\uFEFFRecipient,Channel,Subject or Preview,Sent By,Sent Date,Status,Delivery Date,Error Message\r\n");foreach(DataRow r in x.Rows.Rows)b.AppendLine(Csv(r["Recipient"])+","+Csv(r["Channel"])+","+Csv(r["Subject"])+","+Csv(r["SentBy"])+","+Csv(r["SentAt"])+","+Csv(r["Status"])+","+Csv(r["DeliveredAt"])+","+Csv(r["FailureReason"]));Repo.Log(UserId,"DELIVERY_EXPORTED","Filtered delivery log exported; "+x.Rows.Rows.Count+" rows",Ip);Response.Clear();Response.ContentType="text/csv";Response.AddHeader("Content-Disposition","attachment; filename=communication-deliveries-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".csv");Response.BinaryWrite(Encoding.UTF8.GetBytes(b.ToString()));Response.End();}void Error(string m){litMessage.Text="<div class='comm-error' role='alert'>"+H(m)+"</div>";}}}
